                TEST_ASSERT(c1 == Q_CTRL16_1(nr, (pf?1:0)), "Q.4.NEW RR mod-128 ctrl[1] == 0x80 (N(R)=64<<1|P/F=0)", c1);
                DEBUG_PRINT("Q.4.NEW RR-16 ctrl[0]=0x%02X ctrl[1]=0x%02X", c0, c1);
